export default () => {
    const mxcad = new McObject()
    mxcad.create({
      canvas: "#myCanvas",
      locateFile: (fileName: string)=> {
            // CDN loading must use resources in wasm/ 2D-ST, because github restrictions cannot use wasm/2d resources
            // Use wasm/2d to comply with the browser same-origin policy or use other means to circumvent the browser same-origin policy
            return self.location.origin + "/mxcad/wasm/2d-st/" + fileName
      },
      // The directory location where the font is loaded
      fontspath: self.location.origin + "/mxcad/fonts",
      // Load the converted drawing file
      fileUrl: self.location.origin + "/mxcad/test.mxweb",
      onOpenFileComplete: ()=>{
            // Build a rectangular region
            const createRect = (x: number, y: number, w: number, h: number) => {
              const region = new McDbMxRegion()
              const pts = new McGePoint3dArray()
              pts.append(new McGePoint3d(x, y, 0))
              pts.append(new McGePoint3d(x + w, y, 0))
              pts.append(new McGePoint3d(x + w, y + h, 0))
              pts.append(new McGePoint3d(x, y + h, 0))
              region.addContour(pts)
              return region
            }
            // Build a circular region
            const createCircleRegion = (cx: number, cy: number, r: number) => {
              const region = new McDbMxRegion()
              region.addEntityContour(new McDbCircle(cx, cy, 0, r))
              return region
            }

            // Union (yellow): merge the entire area covered by the rectangle and the circle
            createRect(0, 0, 100, 80)
              .booleanOption(McDb.BooleanOptionType.Union, createCircleRegion(100, 40, 50))
              .forEach(item => { item.trueColor = new McCmColor(255, 233, 0); mxcad.drawEntity(item) })

            // Intersection (red): keep only the common overlapping part of the rectangle and the circle
            createRect(250, 0, 100, 80)
              .booleanOption(McDb.BooleanOptionType.Intersection, createCircleRegion(350, 40, 50))
              .forEach(item => { item.trueColor = new McCmColor(255, 0, 0); mxcad.drawEntity(item) })

            // Difference (green): subtract the part overlapping with the circle from the rectangle
            createRect(500, 0, 100, 80)
              .booleanOption(McDb.BooleanOptionType.Difference, createCircleRegion(600, 40, 50))
              .forEach(item => { item.trueColor = new McCmColor(0, 255, 0); mxcad.drawEntity(item) })

            // Xor (blue): keep the non-overlapping parts of the rectangle and the circle
            createRect(750, 0, 100, 80)
              .booleanOption(McDb.BooleanOptionType.Xor, createCircleRegion(850, 40, 50))
              .forEach(item => { item.trueColor = new McCmColor(0, 128, 255); mxcad.drawEntity(item) })

            // Boundary offset (cyan): expand the rectangle boundary outward by 10 as a whole
            const inflated = createRect(0, -160, 100, 80).inflatePaths(10)
            inflated.trueColor = new McCmColor(0, 255, 255)
            mxcad.drawEntity(inflated)

            // Boundary offset (magenta): shrink the rectangle boundary inward by 10 as a whole
            const shrunk = createRect(250, -160, 100, 80).inflatePaths(-10)
            shrunk.trueColor = new McCmColor(255, 0, 255)
            mxcad.drawEntity(shrunk)

            mxcad.zoomAll()
            mxcad.zoomScale(0.8)
      }
    })
    return (<div style="height: 500px; overflow: hidden;"><canvas id="myCanvas" ></canvas>
    </div>)
}
